<!doctype html><html><head><title><?php echo esc_html(get_the_title()); ?></title><meta property="og:type" content="product"><?php wp_head(); ?></head><body><main itemscope itemtype="https://schema.org/Product"><?php while(have_posts()): the_post(); ?><h1 itemprop="name"><?php the_title(); ?></h1><article data-page-id="<?php the_ID(); ?>"><?php echo str_replace('<p>','<p itemprop="description">',apply_filters('the_content',get_the_content())); ?></article><?php endwhile; ?></main></body></html>
